<style>
#loader.kx-loader{display:none;position:fixed;inset:0;z-index:100000;transform:none;pointer-events:auto;background:rgba(4,10,7,.58);backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px)}
.kx-loader__panel{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:min(290px,calc(100vw - 36px));padding:25px 22px 21px;border:1px solid rgba(74,222,128,.28);border-radius:24px;background:linear-gradient(145deg,rgba(18,31,25,.97),rgba(9,17,14,.98));box-shadow:0 24px 80px rgba(0,0,0,.45),inset 0 1px rgba(255,255,255,.07);color:#eef8f0;text-align:center;overflow:hidden}
.kx-loader__panel:before{content:"";position:absolute;width:170px;height:110px;left:50%;top:-75px;transform:translateX(-50%);border-radius:50%;background:rgba(0,204,80,.2);filter:blur(22px)}
.kx-loader__brand{position:relative;display:flex;justify-content:center;align-items:center;gap:10px;margin-bottom:17px;font-size:14px;font-weight:800;letter-spacing:.01em}
.kx-loader__brand img{width:34px;height:34px;object-fit:cover;border-radius:11px;box-shadow:0 0 18px rgba(0,204,80,.22)}
.kx-loader__classic,.kx-loader__festive,.kx-loader__christmas{display:none}
#loader.kx-loader--classic .kx-loader__classic,#loader.kx-loader--festive .kx-loader__festive,#loader.kx-loader--christmas .kx-loader__christmas{display:block}
.kx-loader__variant{display:none}
#loader.kx-loader--aurora .kx-loader__variant,#loader.kx-loader--orbit .kx-loader__variant,#loader.kx-loader--gold .kx-loader__variant,#loader.kx-loader--ocean .kx-loader__variant,#loader.kx-loader--cosmic .kx-loader__variant,#loader.kx-loader--matrix .kx-loader__variant,#loader.kx-loader--neon .kx-loader__variant{display:block}
.kx-loader__ring{width:42px;height:42px;margin:0 auto 13px;border-radius:50%;border:3px solid rgba(255,255,255,.1);border-top-color:#35e878;border-right-color:#0cae45;animation:kx-loader-spin .85s linear infinite}
.kx-loader__classic .kx-loader__ring{width:30px;height:30px;border-width:3px;margin-bottom:10px}
.kx-loader__title{font-size:.95rem;font-weight:750;line-height:1.35;margin:0;color:#f5fff7}
.kx-loader__hint{font-size:.76rem;color:#9caea2;margin:5px 0 0}
/* A layered tree, glass-like baubles, and soft snowfall create the seasonal 3D scene. */
.kx-festive-scene{height:118px;position:relative;margin:0 auto 7px;perspective:450px;overflow:hidden;border-radius:17px;background:radial-gradient(ellipse at 50% 90%,rgba(49,207,105,.2),transparent 58%)}
.kx-festive-tree{position:absolute;left:50%;bottom:14px;width:87px;height:97px;transform:translateX(-50%) rotateX(7deg);filter:drop-shadow(0 10px 12px rgba(0,0,0,.35))}
.kx-festive-tree i{position:absolute;left:50%;width:0;height:0;transform:translateX(-50%);border-left:var(--w) solid transparent;border-right:var(--w) solid transparent;border-bottom:var(--h) solid var(--c);filter:drop-shadow(0 4px 7px rgba(0,0,0,.18))}
.kx-festive-tree i:nth-child(1){--w:18px;--h:29px;--c:#49df88;top:5px}.kx-festive-tree i:nth-child(2){--w:29px;--h:37px;--c:#179e5a;top:25px}.kx-festive-tree i:nth-child(3){--w:40px;--h:43px;--c:#087345;top:48px}
.kx-festive-tree:after{content:"";position:absolute;left:38px;bottom:0;width:12px;height:19px;border-radius:2px;background:linear-gradient(90deg,#71431e,#bb7d3b,#71431e)}
.kx-festive-star{position:absolute;top:2px;left:50%;z-index:2;transform:translateX(-50%);color:#ffe8a1;font-size:19px;text-shadow:0 0 13px #ffc947;animation:kx-twinkle 1.8s ease-in-out infinite}
.kx-bauble{position:absolute;z-index:3;width:11px;height:11px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#fff6d6,#ffcb5c 32%,#b76b18 78%);box-shadow:0 0 10px rgba(255,192,76,.45);animation:kx-float 2.7s ease-in-out infinite}
.kx-bauble:nth-child(3){left:calc(50% - 19px);top:55px}.kx-bauble:nth-child(4){left:calc(50% + 13px);top:75px;background:radial-gradient(circle at 30% 25%,#e8ffff,#70dcff 35%,#217da0 80%);animation-delay:.6s}.kx-bauble:nth-child(5){left:calc(50% - 31px);top:91px;background:radial-gradient(circle at 30% 25%,#fff1f1,#ff7787 35%,#982f50 80%);animation-delay:1s}
.kx-snow{position:absolute;top:-10px;color:#ecfff3;opacity:.75;font-size:8px;animation:kx-snowfall 3.8s linear infinite}.kx-snow:nth-child(1){left:14%;animation-delay:.2s}.kx-snow:nth-child(2){left:32%;animation-delay:1.6s}.kx-snow:nth-child(3){left:70%;animation-delay:.8s}.kx-snow:nth-child(4){left:87%;animation-delay:2.2s}
.kx-festive-progress{height:4px;border-radius:9px;background:rgba(255,255,255,.1);margin:13px 3px 0;overflow:hidden}.kx-festive-progress i{display:block;height:100%;width:38%;border-radius:9px;background:linear-gradient(90deg,#35e878,#ffe19b);box-shadow:0 0 10px rgba(255,222,139,.6);animation:kx-progress 1.8s ease-in-out infinite alternate}
.kx-christmas-scene{height:118px;position:relative;margin:0 auto 7px;perspective:450px;overflow:hidden;border-radius:17px;background:radial-gradient(ellipse at 50% 90%,rgba(178,35,53,.24),transparent 58%),linear-gradient(160deg,rgba(13,65,44,.42),rgba(18,25,22,.18))}
.kx-christmas-tree{position:absolute;left:50%;bottom:13px;width:87px;height:97px;transform:translateX(-50%) rotateX(8deg);filter:drop-shadow(0 10px 12px rgba(0,0,0,.38));animation:kx-tree-sway 4s ease-in-out infinite}
.kx-christmas-tree i{position:absolute;left:50%;width:0;height:0;transform:translateX(-50%);border-left:var(--w) solid transparent;border-right:var(--w) solid transparent;border-bottom:var(--h) solid var(--c);filter:drop-shadow(0 4px 7px rgba(0,0,0,.2))}
.kx-christmas-tree i:nth-child(1){--w:18px;--h:29px;--c:#53d68a;top:5px}.kx-christmas-tree i:nth-child(2){--w:29px;--h:37px;--c:#168d55;top:25px}.kx-christmas-tree i:nth-child(3){--w:40px;--h:43px;--c:#08623c;top:48px}
.kx-christmas-tree:after{content:"";position:absolute;left:38px;bottom:0;width:12px;height:19px;border-radius:2px;background:linear-gradient(90deg,#71431e,#bb7d3b,#71431e)}
.kx-christmas-star{position:absolute;top:2px;left:50%;z-index:2;transform:translateX(-50%);color:#ffe5a0;font-size:20px;text-shadow:0 0 14px #ffc947;animation:kx-twinkle 1.8s ease-in-out infinite}
.kx-christmas-bauble{position:absolute;z-index:3;width:11px;height:11px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#fff8d8,#f5c85c 34%,#ad6418 80%);box-shadow:0 0 11px rgba(255,205,92,.6);animation:kx-float 2.6s ease-in-out infinite}
.kx-christmas-bauble:nth-child(3){left:calc(50% - 19px);top:55px}.kx-christmas-bauble:nth-child(4){left:calc(50% + 13px);top:75px;background:radial-gradient(circle at 30% 25%,#fff0f0,#f77983 35%,#a12642 80%);animation-delay:.6s}.kx-christmas-bauble:nth-child(5){left:calc(50% - 31px);top:91px;background:radial-gradient(circle at 30% 25%,#f2ffff,#7fd8ed 35%,#22758b 80%);animation-delay:1s}
.kx-christmas-gift{position:absolute;z-index:2;bottom:10px;width:22px;height:18px;border-radius:3px;box-shadow:0 5px 8px rgba(0,0,0,.28);animation:kx-gift-bob 2.8s ease-in-out infinite}.kx-christmas-gift:before{content:"";position:absolute;left:9px;top:0;width:4px;height:100%;background:rgba(255,236,198,.8)}.kx-christmas-gift:after{content:"";position:absolute;left:6px;top:-5px;width:10px;height:6px;border:2px solid #f6d88d;border-radius:50% 50% 0 50%;transform:rotate(18deg)}.kx-christmas-gift--red{left:calc(50% - 53px);background:linear-gradient(135deg,#f47778,#b6273e)}.kx-christmas-gift--gold{left:calc(50% + 34px);bottom:14px;background:linear-gradient(135deg,#f6d47e,#b77a23);animation-delay:.7s}
.kx-loader--christmas .kx-loader__panel{border-color:rgba(217,73,83,.36);background:linear-gradient(145deg,rgba(18,37,31,.98),rgba(20,24,24,.99))}.kx-loader--christmas .kx-loader__panel:before{background:rgba(190,40,58,.24)}.kx-loader--christmas .kx-festive-progress i{background:linear-gradient(90deg,#39cf7d,#f2d07a,#d84250)}
.kx-variant-stage{--kx-accent:#64e8d7;--kx-secondary:#68a9ff;position:relative;display:grid;place-items:center;width:114px;height:106px;margin:0 auto 14px;border-radius:25px;isolation:isolate;background:radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--kx-accent) 20%,transparent),transparent 67%),rgba(255,255,255,.025);perspective:500px}
.kx-variant-orbit{position:absolute;width:72px;height:72px;border:1px solid color-mix(in srgb,var(--kx-accent) 54%,transparent);border-radius:50%;box-shadow:0 0 14px color-mix(in srgb,var(--kx-accent) 16%,transparent);animation:kx-variant-spin 3.2s linear infinite}
.kx-variant-orbit--one{transform:rotateX(68deg) rotateZ(0)}.kx-variant-orbit--two{width:60px;height:60px;border-color:color-mix(in srgb,var(--kx-secondary) 56%,transparent);transform:rotateY(68deg);animation-duration:4.2s;animation-direction:reverse}.kx-variant-orbit--three{width:47px;height:47px;border-style:dashed;border-color:color-mix(in srgb,var(--kx-accent) 46%,transparent);animation-duration:8s}
.kx-variant-core{z-index:1;display:grid;place-items:center;width:35px;height:35px;border:1px solid color-mix(in srgb,var(--kx-accent) 62%,transparent);border-radius:12px;background:linear-gradient(145deg,color-mix(in srgb,var(--kx-accent) 24%,#14231d),rgba(6,15,12,.94));box-shadow:0 0 24px color-mix(in srgb,var(--kx-accent) 30%,transparent),inset 0 1px rgba(255,255,255,.2);color:#f4fff8;font-size:15px;font-weight:900;animation:kx-core-breathe 2.2s ease-in-out infinite}
.kx-variant-spark{position:absolute;color:var(--kx-accent);font-size:12px;text-shadow:0 0 12px var(--kx-accent);animation:kx-sparkle 1.7s ease-in-out infinite}.kx-variant-spark--one{top:14px;right:21px}.kx-variant-spark--two{left:18px;bottom:17px;color:var(--kx-secondary);animation-delay:.8s}
.kx-loader--aurora .kx-variant-stage{--kx-accent:#64f2d0;--kx-secondary:#718dff;background:radial-gradient(ellipse at 30% 80%,rgba(56,211,185,.19),transparent 45%),radial-gradient(ellipse at 80% 20%,rgba(100,105,255,.2),transparent 45%),rgba(255,255,255,.025)}.kx-loader--aurora .kx-loader__panel{border-color:rgba(100,242,208,.34)}.kx-loader--aurora .kx-loader__panel:before{background:rgba(62,220,194,.2)}
.kx-loader--orbit .kx-variant-stage{--kx-accent:#61d9ff;--kx-secondary:#c582ff;background:radial-gradient(circle,rgba(73,132,255,.19),transparent 69%),rgba(255,255,255,.025)}.kx-loader--orbit .kx-variant-orbit--one{width:85px;height:52px}.kx-loader--orbit .kx-variant-orbit--two{width:86px;height:56px}.kx-loader--orbit .kx-loader__panel{border-color:rgba(97,217,255,.34)}
.kx-loader--gold .kx-variant-stage{--kx-accent:#f4d17f;--kx-secondary:#fff1c6;background:radial-gradient(circle,rgba(191,139,45,.2),transparent 70%),rgba(255,255,255,.02)}.kx-loader--gold .kx-variant-orbit{border-radius:18px;transform:rotate(45deg);border-color:rgba(244,209,127,.55)}.kx-loader--gold .kx-variant-orbit--two{border-radius:50%;transform:rotateY(67deg)}.kx-loader--gold .kx-loader__panel{border-color:rgba(244,209,127,.34)}.kx-loader--gold .kx-loader__panel:before{background:rgba(214,166,65,.2)}
.kx-loader--ocean .kx-variant-stage{--kx-accent:#45e3dc;--kx-secondary:#52a9e9;background:linear-gradient(180deg,rgba(37,140,191,.12),rgba(27,205,190,.12)),rgba(255,255,255,.02);border-radius:50% 50% 27px 27px}.kx-loader--ocean .kx-variant-orbit{width:84px;height:34px;border-radius:50%;transform:rotateX(66deg)}.kx-loader--ocean .kx-variant-orbit--two{width:65px;height:28px}.kx-loader--ocean .kx-loader__panel{border-color:rgba(69,227,220,.32)}
.kx-loader--cosmic .kx-variant-stage{--kx-accent:#b48cff;--kx-secondary:#ff86d6;background:radial-gradient(circle at 48% 48%,rgba(115,66,203,.24),transparent 68%),rgba(255,255,255,.02)}.kx-loader--cosmic .kx-variant-orbit{width:87px;height:52px;border-color:rgba(180,140,255,.65)}.kx-loader--cosmic .kx-variant-orbit--two{width:83px;height:48px;border-color:rgba(255,134,214,.6)}.kx-loader--cosmic .kx-loader__panel{border-color:rgba(180,140,255,.35)}
.kx-loader--matrix .kx-variant-stage{--kx-accent:#6bff9b;--kx-secondary:#22c55e;background:repeating-linear-gradient(0deg,rgba(79,255,143,.05) 0 1px,transparent 1px 11px),repeating-linear-gradient(90deg,rgba(79,255,143,.04) 0 1px,transparent 1px 11px),rgba(0,20,10,.38);border-radius:12px}.kx-loader--matrix .kx-variant-orbit{border-radius:8px;border-style:dashed;transform:rotate(45deg)}.kx-loader--matrix .kx-variant-orbit--two{transform:rotate(-45deg)}.kx-loader--matrix .kx-loader__panel{border-color:rgba(107,255,155,.35)}
.kx-loader--neon .kx-variant-stage{--kx-accent:#ff65d4;--kx-secondary:#58e7ff;background:radial-gradient(circle,rgba(244,69,191,.15),transparent 65%),rgba(255,255,255,.02)}.kx-loader--neon .kx-variant-orbit{width:78px;height:78px;border:2px solid rgba(255,101,212,.43);box-shadow:0 0 17px rgba(255,101,212,.18),inset 0 0 17px rgba(88,231,255,.12)}.kx-loader--neon .kx-variant-orbit--two{width:58px;height:58px;border-color:rgba(88,231,255,.6)}.kx-loader--neon .kx-loader__panel{border-color:rgba(255,101,212,.34)}
@keyframes kx-loader-spin{to{transform:rotate(360deg)}}@keyframes kx-float{50%{transform:translateY(-5px) scale(1.08)}}@keyframes kx-twinkle{50%{filter:brightness(1.4);transform:translateX(-50%) scale(1.18)}}@keyframes kx-snowfall{to{transform:translateY(140px) translateX(12px);opacity:0}}@keyframes kx-progress{to{width:92%}}@keyframes kx-tree-sway{50%{transform:translateX(-50%) rotateX(8deg) rotateZ(1.2deg)}}@keyframes kx-gift-bob{50%{translate:0 -3px}}@keyframes kx-variant-spin{to{rotate:360deg}}@keyframes kx-core-breathe{50%{scale:1.12;box-shadow:0 0 32px color-mix(in srgb,var(--kx-accent) 50%,transparent)}}@keyframes kx-sparkle{50%{scale:.7;opacity:.55;rotate:35deg}}
@media(prefers-reduced-motion:reduce){.kx-loader__ring,.kx-bauble,.kx-festive-star,.kx-snow,.kx-festive-progress i,.kx-christmas-tree,.kx-christmas-bauble,.kx-christmas-gift,.kx-variant-orbit,.kx-variant-core,.kx-variant-spark{animation:none!important}.kx-snow{display:none}}
body.kx-light #loader.kx-loader{background:rgba(17,28,20,.34)}
body.kx-light .kx-loader__panel{background:linear-gradient(145deg,rgba(255,255,255,.98),rgba(239,248,241,.99));color:#132219;border-color:rgba(0,150,60,.2);box-shadow:0 24px 80px rgba(16,40,24,.2)}
body.kx-light .kx-loader__title{color:#132219}body.kx-light .kx-loader__hint{color:#5d7062}
</style>
